use ascent_aero::{
    stability_calibers_at, stability_pct_of_length_at, FlightQuantities, NoseShape, PointMass,
    RulePack, Vehicle,
};
use ascent_domain::Motor;
use ascent_sim::{
    simulate_vertical, AtmosphereModel, DragModel, Environment, Recovery, Rocket, SimConfig,
    SimResult,
};
use serde::{Deserialize, Serialize};

pub const BALLAST_NAME: &str = "solver ballast";

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ChuteConfig {
    pub cd: f64,
    pub area_m2: f64,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ReviewDesign {
    pub vehicle: Vehicle,
    pub nose_shape: NoseShape,
    pub cd: f64,
    pub chute: Option<ChuteConfig>,
    pub rail_length_m: f64,
    pub motor_designation: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Review {
    pub apogee_m: f64,
    pub rail_exit_velocity_ms: f64,
    pub quantities: FlightQuantities,
    pub checks: Vec<ascent_aero::CheckResult>,
    pub feasible: bool,
}

fn to_rocket(design: &ReviewDesign) -> Rocket {
    let r = design.vehicle.diameter_m() / 2.0;
    Rocket {
        name: design.vehicle.name.clone(),
        dry_mass_kg: design.vehicle.dry_mass_kg(),
        drag: Some(DragModel {
            cd: design.cd,
            reference_area_m2: std::f64::consts::PI * r * r,
        }),
        recovery: design.chute.as_ref().map(|c| Recovery {
            chute_cd: c.cd,
            chute_area_m2: c.area_m2,
        }),
    }
}

fn fly(design: &ReviewDesign, motor: &Motor) -> SimResult {
    let env = Environment {
        gravity_ms2: 9.80665,
        atmosphere: AtmosphereModel::Standard,
        rail_length_m: design.rail_length_m,
    };
    simulate_vertical(&to_rocket(design), motor, &env, &SimConfig::default())
}

/// Measure every rule-bound quantity. Stability is sampled across the burn
/// (CG moves monotonically for a rear motor, but sampling is cheap and makes
/// no monotonicity assumption).
fn measure(design: &ReviewDesign, motor: &Motor, result: &SimResult) -> FlightQuantities {
    let v = &design.vehicle;
    let burn = motor.burn_time();
    const SAMPLES: usize = 32;
    let mut min_cal = f64::INFINITY;
    let mut min_pct = f64::INFINITY;
    let mut max_pct = f64::NEG_INFINITY;
    for i in 0..=SAMPLES {
        let t = burn * i as f64 / SAMPLES as f64;
        min_cal = min_cal.min(stability_calibers_at(v, design.nose_shape, motor, t));
        let pct = stability_pct_of_length_at(v, design.nose_shape, motor, t);
        min_pct = min_pct.min(pct);
        max_pct = max_pct.max(pct);
    }
    FlightQuantities {
        rail_exit_velocity_ms: result.rail_exit_velocity_ms,
        min_stability_calibers: min_cal,
        fin_span_calibers: v.fins.span_m / v.diameter_m(),
        stability_pct_len_at_launch: stability_pct_of_length_at(v, design.nose_shape, motor, 0.0),
        stability_pct_len_min: min_pct,
        stability_pct_len_max: max_pct,
    }
}

pub fn evaluate(design: &ReviewDesign, motor: &Motor, rules: &RulePack) -> Review {
    let result = fly(design, motor);
    let quantities = measure(design, motor, &result);
    let checks = rules.check(&quantities);
    let feasible = checks.iter().all(|c| c.pass);
    Review {
        apogee_m: result.apogee_m,
        rail_exit_velocity_ms: result.rail_exit_velocity_ms,
        quantities,
        checks,
        feasible,
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct DiffEntry {
    pub field: String,
    pub before: String,
    pub after: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Repair {
    pub design: ReviewDesign,
    pub review: Review,
    pub target_apogee_m: f64,
    pub achieved_apogee_m: f64,
    pub diff: Vec<DiffEntry>,
}

fn with_ballast(design: &ReviewDesign, ballast_kg: f64) -> ReviewDesign {
    let mut d = design.clone();
    d.vehicle.point_masses.retain(|p| p.name != BALLAST_NAME);
    if ballast_kg > 0.0 {
        d.vehicle.point_masses.push(PointMass {
            name: BALLAST_NAME.into(),
            mass_kg: ballast_kg,
            position_from_nose_m: d.vehicle.nose.length_m,
        });
    }
    d
}

fn existing_ballast_kg(design: &ReviewDesign) -> f64 {
    design
        .vehicle
        .point_masses
        .iter()
        .filter(|p| p.name == BALLAST_NAME)
        .map(|p| p.mass_kg)
        .sum()
}

/// Repair an infeasible design: for each candidate motor (in the caller's
/// order — deterministic), bisect nose ballast so apogee lands within
/// `tolerance_m` of `target_apogee_m`, then require every rule to pass.
/// Returns the first fully feasible repair, with a diff of every change.
pub fn solve(
    design: &ReviewDesign,
    motors: &[Motor],
    rules: &RulePack,
    target_apogee_m: f64,
    tolerance_m: f64,
) -> Result<Repair, String> {
    const MAX_BALLAST_KG: f64 = 2.0;
    const BISECT_ITERS: usize = 60;

    let mut reasons: Vec<String> = Vec::new();
    for motor in motors {
        let mut candidate = with_ballast(design, 0.0);
        candidate.motor_designation = motor.designation.clone();

        let apogee_bare = fly(&candidate, motor).apogee_m;
        if apogee_bare + tolerance_m < target_apogee_m {
            reasons.push(format!(
                "{}: max apogee {:.0} m below target",
                motor.designation, apogee_bare
            ));
            continue;
        }

        let mut ballast = 0.0;
        if (apogee_bare - target_apogee_m).abs() > tolerance_m {
            let (mut lo, mut hi) = (0.0_f64, MAX_BALLAST_KG);
            let apogee_heavy = fly(&with_ballast(&candidate, hi), motor).apogee_m;
            if apogee_heavy > target_apogee_m + tolerance_m {
                reasons.push(format!(
                    "{}: even {} kg ballast leaves apogee {:.0} m above target",
                    motor.designation, MAX_BALLAST_KG, apogee_heavy
                ));
                continue;
            }
            for _ in 0..BISECT_ITERS {
                let mid = (lo + hi) / 2.0;
                let apogee = fly(&with_ballast(&candidate, mid), motor).apogee_m;
                if apogee > target_apogee_m {
                    lo = mid;
                } else {
                    hi = mid;
                }
            }
            ballast = (lo + hi) / 2.0;
        }

        let repaired = with_ballast(&candidate, ballast);
        let review = evaluate(&repaired, motor, rules);
        let apogee_err = (review.apogee_m - target_apogee_m).abs();
        if apogee_err > tolerance_m {
            reasons.push(format!(
                "{}: could not settle within ±{} m of target",
                motor.designation, tolerance_m
            ));
            continue;
        }
        if !review.feasible {
            let failed: Vec<&str> = review
                .checks
                .iter()
                .filter(|c| !c.pass)
                .map(|c| c.rule_id.as_str())
                .collect();
            reasons.push(format!("{}: violates {}", motor.designation, failed.join(", ")));
            continue;
        }

        let mut diff = Vec::new();
        if design.motor_designation != motor.designation {
            diff.push(DiffEntry {
                field: "motor".into(),
                before: design.motor_designation.clone(),
                after: motor.designation.clone(),
            });
        }
        let before_ballast = existing_ballast_kg(design);
        if (before_ballast - ballast).abs() > 1e-6 {
            diff.push(DiffEntry {
                field: "nose ballast".into(),
                before: format!("{:.1} g", before_ballast * 1000.0),
                after: format!("{:.1} g", ballast * 1000.0),
            });
        }
        let achieved = review.apogee_m;
        return Ok(Repair {
            design: repaired,
            review,
            target_apogee_m,
            achieved_apogee_m: achieved,
            diff,
        });
    }
    Err(if reasons.is_empty() {
        "no candidate motors supplied".into()
    } else {
        format!("no feasible configuration found: {}", reasons.join("; "))
    })
}
use serde::{Deserialize, Serialize};

/// Stable per-vehicle part identifier. Commands (Step 2) and mesh part
/// ranges (Step 3) address parts by this id, so ids never get reused.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord, Serialize, Deserialize)]
pub struct PartId(pub u32);

#[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum NoseShape {
    TangentOgive,
    Conical,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(tag = "type", rename_all = "snake_case")]
pub enum PartKind {
    NoseCone {
        shape: NoseShape,
        length_m: f64,
        base_radius_m: f64,
        mass_g: f64,
    },
    BodyTube {
        length_m: f64,
        outer_radius_m: f64,
        wall_mm: f64,
        mass_g: f64,
    },
    Transition {
        length_m: f64,
        fore_radius_m: f64,
        aft_radius_m: f64,
        mass_g: f64,
    },
    /// Joins two stages. Everything from the coupler down (aft) is the
    /// lower stage; the coupler drops with it at separation.
    StageCoupler {
        length_m: f64,
        outer_radius_m: f64,
        mass_g: f64,
        /// Delay after the lower stage's burnout before it separates.
        separation_delay_s: f64,
    },
    /// Trailing edge sits flush with the parent tube's aft end.
    FinSet {
        count: u32,
        root_chord_m: f64,
        tip_chord_m: f64,
        span_m: f64,
        sweep_m: f64,
        thickness_mm: f64,
        mass_g: f64,
    },
    MotorMount {
        motor_designation: String,
        length_m: f64,
        /// Fore end of the mount, measured from the parent's fore end.
        position_m: f64,
        mass_g: f64,
    },
    Parachute {
        diameter_cm: f64,
        cd: f64,
        /// Packed location, measured from the parent's fore end.
        position_m: f64,
        mass_g: f64,
    },
    MassComponent {
        name: String,
        /// Point location, measured from the parent's fore end.
        position_m: f64,
        mass_g: f64,
    },
}

impl PartKind {
    pub fn mass_g(&self) -> f64 {
        match self {
            PartKind::NoseCone { mass_g, .. }
            | PartKind::BodyTube { mass_g, .. }
            | PartKind::Transition { mass_g, .. }
            | PartKind::StageCoupler { mass_g, .. }
            | PartKind::FinSet { mass_g, .. }
            | PartKind::MotorMount { mass_g, .. }
            | PartKind::Parachute { mass_g, .. }
            | PartKind::MassComponent { mass_g, .. } => *mass_g,
        }
    }

    /// Structural parts stack and define the airframe; everything else
    /// attaches to one.
    pub fn is_structural(&self) -> bool {
        matches!(
            self,
            PartKind::NoseCone { .. }
                | PartKind::BodyTube { .. }
                | PartKind::Transition { .. }
                | PartKind::StageCoupler { .. }
        )
    }

    fn structural_length_m(&self) -> f64 {
        match self {
            PartKind::NoseCone { length_m, .. }
            | PartKind::BodyTube { length_m, .. }
            | PartKind::Transition { length_m, .. }
            | PartKind::StageCoupler { length_m, .. } => *length_m,
            _ => 0.0,
        }
    }
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct Part {
    pub id: PartId,
    pub kind: PartKind,
    #[serde(default)]
    pub children: Vec<Part>,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct Vehicle {
    pub name: String,
    pub parts: Vec<Part>,
}

#[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize)]
pub struct MassProperties {
    pub total_mass_g: f64,
    pub cg_from_nose_m: f64,
    /// Pitch/yaw moment of inertia about the CG, kg·m².
    pub longitudinal_moi_kg_m2: f64,
}

impl Vehicle {
    /// Airframe length: the structural stack, nose tip to aft end.
    pub fn stack_length_m(&self) -> f64 {
        self.parts.iter().map(|p| p.kind.structural_length_m()).sum()
    }

    /// Tree invariants: root parts structural, attachments only as
    /// children of structural parts, ids unique, masses non-negative.
    pub fn validate(&self) -> Result<(), String> {
        let mut seen = std::collections::BTreeSet::new();
        for part in &self.parts {
            if !part.kind.is_structural() {
                return Err(format!(
                    "part {} is an attachment and cannot sit at root level",
                    part.id.0
                ));
            }
            validate_part(part, &mut seen)?;
        }
        for (i, part) in self.parts.iter().enumerate() {
            if matches!(part.kind, PartKind::StageCoupler { .. })
                && (i == 0 || i == self.parts.len() - 1)
            {
                return Err(format!(
                    "stage coupler {} must sit between structural parts, not at the stack end",
                    part.id.0
                ));
            }
        }
        Ok(())
    }

    /// Stage segments, nose-first (top stage first; burn order is the
    /// reverse). A stage begins at each `StageCoupler` — the coupler
    /// drops with the stage below it. A vehicle with no couplers is one
    /// stage.
    pub fn stages(&self) -> Vec<StageInfo> {
        let mut boundaries = vec![0];
        for (i, part) in self.parts.iter().enumerate() {
            if matches!(part.kind, PartKind::StageCoupler { .. }) {
                boundaries.push(i);
            }
        }
        boundaries.push(self.parts.len());
        boundaries.dedup();

        boundaries
            .windows(2)
            .map(|w| {
                let (start, end) = (w[0], w[1]);
                let segment = &self.parts[start..end];
                let mut dry_mass_g = 0.0;
                let mut motor_designation = None;
                for part in segment {
                    dry_mass_g += subtree_mass_g(part);
                    find_motor_mount(part, &mut motor_designation);
                }
                let separation_delay_s = match &self.parts[start].kind {
                    PartKind::StageCoupler {
                        separation_delay_s, ..
                    } => Some(*separation_delay_s),
                    _ => None,
                };
                StageInfo {
                    part_range: (start, end),
                    dry_mass_g,
                    motor_designation,
                    separation_delay_s,
                }
            })
            .collect()
    }

    /// Mass, CG, and pitch MOI rollup. Approximations per part type are
    /// the documented worksheet formulas (VEHICLE_TREE.md): slender parts
    /// are thin rods (m·L²/12 own inertia), attachments without length
    /// are point masses; parallel-axis everywhere.
    pub fn mass_properties(&self) -> MassProperties {
        let mut items: Vec<(f64, f64, f64)> = Vec::new();
        let mut cursor = 0.0;
        for part in &self.parts {
            let fore = cursor;
            let length = part.kind.structural_length_m();
            collect_mass_items(part, fore, length, &mut items);
            cursor += length;
        }

        let total_kg: f64 = items.iter().map(|(m, _, _)| m).sum();
        if total_kg == 0.0 {
            return MassProperties {
                total_mass_g: 0.0,
                cg_from_nose_m: 0.0,
                longitudinal_moi_kg_m2: 0.0,
            };
        }
        let cg = items.iter().map(|(m, x, _)| m * x).sum::<f64>() / total_kg;
        let moi = items
            .iter()
            .map(|(m, x, own)| own + m * (x - cg) * (x - cg))
            .sum::<f64>();
        MassProperties {
            total_mass_g: total_kg * 1000.0,
            cg_from_nose_m: cg,
            longitudinal_moi_kg_m2: moi,
        }
    }
}

/// One stage segment of the root stack, nose-first indices.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct StageInfo {
    /// Root-part indices `[start, end)` of this stage's segment.
    pub part_range: (usize, usize),
    /// Dry mass of the segment including all attachments, grams.
    pub dry_mass_g: f64,
    /// Designation of the first motor mount found in the segment.
    pub motor_designation: Option<String>,
    /// `Some` for stages that begin at a coupler (everything below the
    /// top stage): delay after this stage's burnout before it drops.
    pub separation_delay_s: Option<f64>,
}

fn subtree_mass_g(part: &Part) -> f64 {
    part.kind.mass_g() + part.children.iter().map(subtree_mass_g).sum::<f64>()
}

fn find_motor_mount(part: &Part, found: &mut Option<String>) {
    if found.is_none() {
        if let PartKind::MotorMount {
            motor_designation, ..
        } = &part.kind
        {
            *found = Some(motor_designation.clone());
        }
    }
    for child in &part.children {
        find_motor_mount(child, found);
    }
}

fn validate_part(part: &Part, seen: &mut std::collections::BTreeSet<u32>) -> Result<(), String> {
    if !seen.insert(part.id.0) {
        return Err(format!("duplicate part id {}", part.id.0));
    }
    if part.kind.mass_g() < 0.0 {
        return Err(format!("part {} has negative mass", part.id.0));
    }
    for child in &part.children {
        if child.kind.is_structural() {
            return Err(format!(
                "part {} is structural and must sit at root level, not nested",
                child.id.0
            ));
        }
        if !child.children.is_empty() {
            return Err(format!("attachment {} cannot have children", child.id.0));
        }
        validate_part(child, seen)?;
    }
    Ok(())
}

/// Worksheet mass model per part (see VEHICLE_TREE.md):
/// - NoseCone: thin conical shell — CG at 2/3·L aft of the tip (the same
///   convention ascent-aero's dry_cg_from_nose_m uses), thin-rod own MOI.
/// - BodyTube / Transition: CG at mid-length, thin-rod own MOI.
/// - FinSet: point mass, CG half a root chord ahead of the parent's aft end.
/// - MotorMount: CG at mount mid-length, thin-rod own MOI.
/// - Parachute / MassComponent: point mass at its position.
fn collect_mass_items(
    part: &Part,
    parent_fore_m: f64,
    parent_length_m: f64,
    items: &mut Vec<(f64, f64, f64)>,
) {
    let mass_kg = part.kind.mass_g() / 1000.0;
    match &part.kind {
        PartKind::NoseCone { length_m, .. } => {
            items.push((
                mass_kg,
                parent_fore_m + 2.0 / 3.0 * length_m,
                mass_kg * length_m * length_m / 12.0,
            ));
        }
        PartKind::BodyTube { length_m, .. }
        | PartKind::Transition { length_m, .. }
        | PartKind::StageCoupler { length_m, .. } => {
            items.push((
                mass_kg,
                parent_fore_m + length_m / 2.0,
                mass_kg * length_m * length_m / 12.0,
            ));
        }
        PartKind::FinSet { root_chord_m, .. } => {
            items.push((
                mass_kg,
                parent_fore_m + parent_length_m - root_chord_m / 2.0,
                0.0,
            ));
        }
        PartKind::MotorMount {
            length_m,
            position_m,
            ..
        } => {
            items.push((
                mass_kg,
                parent_fore_m + position_m + length_m / 2.0,
                mass_kg * length_m * length_m / 12.0,
            ));
        }
        PartKind::Parachute { position_m, .. } | PartKind::MassComponent { position_m, .. } => {
            items.push((mass_kg, parent_fore_m + position_m, 0.0));
        }
    }
    for child in &part.children {
        collect_mass_items(child, parent_fore_m, parent_length_m, items);
    }
}

