        assert!(matches!(shape, NoseShape::Ogive));
        let hand_built = Vehicle {
            name: "Estes Alpha III".into(),
            nose: NoseCone {
                length_m: 0.075,
                base_diameter_m: 0.025,
                mass_kg: 0.008,
