    pub target_apogee_m: f64,
    pub target_tolerance_m: f64,
    pub target_met: bool,
    pub mission_feasible: bool,
}

pub fn report(target_apogee_m: f64) -> Result<ReviewReport, String> {
    report_for(&ascent_domain::vehicle::reference_vehicle(), &crate::design::Design::reference(), target_apogee_m)
}

pub fn report_for(tree: &TreeVehicle, flat_design: &crate::design::Design, target_apogee_m: f64) -> Result<ReviewReport, String> {
    let design = review_from_tree(tree, flat_design)?;
    let rules = rules()?;
    let motor = motors()
        .into_iter()
        .find(|m| m.designation == design.motor_designation)
        .ok_or("reference motor missing")?;
    let review = evaluate(&design, &motor, &rules);
    let tol = 3.0;
    let target_met = (review.apogee_m - target_apogee_m).abs() <= tol;
    let mission_feasible = review.feasible && target_met;
    Ok(ReviewReport {
        design,
        target_apogee_m,
        target_tolerance_m: tol,
        target_met,
        mission_feasible,
        review,
    })
}

pub fn repair(target_apogee_m: f64) -> Result<Repair, String> {
    repair_for(&ascent_domain::vehicle::reference_vehicle(), &crate::design::Design::reference(), target_apogee_m)
}

pub fn repair_for(tree: &TreeVehicle, flat_design: &crate::design::Design, target_apogee_m: f64) -> Result<Repair, String> {
    let design = review_from_tree(tree, flat_design)?;
    let rules = rules()?;
    solve(&design, &motors(), &rules, target_apogee_m, 3.0)
}

